"boolean\"}, {\"families\": [\"subsets\", \"explicit\"], \"name\": \"is_transitive\", \"summary\": \"Whether the generated group is transitive on 0..n-1.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\", \"explicit\"], \"name\": \"is_primitive\", \"summary\": \"Whether the generated group is transitive and preserves no nontrivial partition of 0..n-1.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\", \"explicit\"], \"name\": \"orbit_partition\", \"summary\": \"Point-orbit labels: point i is labelled by the least point in its orbit.\", \"value\": \"perm_groups.partition\"}, {\"families\": [\"subsets\", \"explicit\"], \"name\": \"base_and_strong_generators\", \"summary\": \"A deterministic BSGS. Repeatedly choose the least point moved by the current stabilizer; use sorted generators and breadth-first Schreier transversals; return the union of level generators sorted lexicographically with duplicates and identity removed.\", \"value\": \"perm_groups.bsgs\"}], \"rejections\": [{\"case\": \"matrix rows are not permutations\", \"error\": \"permutation rows\"}, {\"case\": \"two membership targets\", \"error\": \"exactly one permutation\"}, {\"case\": \"wrong-degree membership target\", \"error\": \"same degree\"}]}, {\"backends\": [{\"accepts\": \"explicit or group_elements families of permutations; cycle_type requires the number of integer partitions of the degree to fit in u64\", \"name\": \"generic\", \"sources\": [\"backends/generic/permutation_statistics_generic.cpp\"], \"summary\": \"Portable C++: parallel per-permutation scans, relation-pruned classical pattern matching, linear cycle decomposition, and dynamic-programming partition ranks.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Permutation_statistics/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"permutation_statistics\", \"reference\": \"lean/Permutation_statistics/Reference.lean\", \"summary\": \"Statistics on permutation families: inversions, descents, major index, complete cycle type, classical pattern avoidance, and strong Bruhat order. Cycle types use a canonical dense partition code.\", \"version\": 1}, \"operations\": [{\"families\": [\"explicit\", \"group_elements\"], \"name\": \"inversions\", \"summary\": \"Number of pairs i < j with w(i) > w(j). Histogram on S_n is the Mahonian distribution.\", \"value\": \"integer\"}, {\"families\": [\"explicit\", \"group_elements\"], \"name\": \"descents\", \"summary\": \"Number of positions i with w(i) > w(i+1). Histogram on S_n is the Eulerian distribution.\", \"value\": \"integer\"}, {\"families\": [\"explicit\", \"group_elements\"], \"name\": \"major_index\", \"summary\": \"Sum of the one-based descent positions i+1.\", \"value\": \"integer\"}, {\"families\": [\"explicit\", \"group_elements\"], \"name\": \"cycle_type\", \"summary\": \"Zero-based rank of the complete cycle-length partition, including fixed points, among partitions of n in descending lexicographic order: [n] has code 0 and [1,...,1] has the last code.\", \"value\": \"integer\"}, {\"args\": {\"patterns\": \"perms\"}, \"families\": [\"explicit\", \"group_elements\"], \"name\": \"pattern_avoids\", \"summary\": \"True exactly when no increasing position subsequence has the relative order of any listed classical pattern. All listed patterns have the degree of the orbits.perms argument.\", \"value\": \"boolean\"}, {\"args\": {\"upper\": \"perms\"}, \"families\": [\"explicit\", \"group_elements\"], \"name\": \"bruhat_leq\", \"summary\": \"Strong Bruhat comparison w <= upper. The upper argument contains exactly one permutation of the same degree; the rank criterion uses every position prefix and upper value threshold.\", \"value\": \"boolean\"}], \"rejections\": [{\"case\": \"matrices are not permutations\", \"error\": \"permutation family\"}, {\"case\": \"Bruhat degree mismatch\", \"error\": \"same degree\"}, {\"case\": \"Bruhat needs one upper bound\", \"error\": \"exactly one\"}, {\"case\": \"S4 inversions\", \"error\": \"does not accept integer\", \"op\": \"inversions\", \"reduction\": \"count\"}, {\"case\": \"S4 avoids 123\", \"error\": \"does not accept boolean\", \"op\": \"pattern_avoids\", \"reduction\": \"histogram\"}]}, {\"backends\": [{\"accepts\": \"any prime q < 2^32, any family of one-row members; `order` and `is_primitive` need q^d < 2^32\", \"name\": \"generic\", \"sources\": [\"backends/generic/polynomials_fq_generic.cpp\"], \"summary\": \"Portable C++: Musser squarefree decomposition and distinct-degree factorisation by repeated Frobenius, Euclid for gcd, Horner for roots, and the walk x, x^2, ... for the order of x. Threads over member ranges.\"}], \"kinds\": [{\"lean\": \"elements\", \"name\": \"polynomials_fq.elements\", \"params\": [\"p\", \"count\"], \"payload\": \"u64 offsets[count+1], then offsets[count] entries of F_p\", \"summary\": \"For each member, a list of field elements (ragged): the roots of `roots`, or the coefficients of the polynomial `gcd` returns.\"}, {\"lean\": \"degrees\", \"name\": \"polynomials_fq.degrees\", \"params\": [\"count\"], \"payload\": \"u64 offsets[count+1], then offsets[count] u64 degrees\", \"summary\": \"For each member, a list of natural numbers (ragged): the degrees `factorisation_degrees` returns.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Polynomials_fq/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"polynomials_fq\", \"reference\": \"lean/Polynomials_fq/Reference.lean\", \"summary\": \"Univariate polynomials over F_q on families of coefficient rows: irreducibility, factorisation degrees, primitivity, the order of x, roots and gcd. A 1 x d member [a_0, ..., a_{d-1}] is the monic polynomial x^d + sum a_i x^i, so all_matrices(q, 1, d) is every monic polynomial of degree d.\", \"version\": 1}, \"operations\": [{\"name\": \"is_irreducible\", \"summary\": \"The member is irreducible over F_q. A member of degree 0 (the polynomial 1) is not.\", \"value\": \"boolean\"}, {\"name\": \"factorisation_degrees\", \"summary\": \"Degrees of the monic irreducible factors of the member, with multiplicity, in non-decreasing order. They sum to the degree.\", \"value\": \"polynomials_fq.degrees\"}, {\"name\": \"is_primitive\", \"summary\": \"The member is a primitive polynomial: irreducible of degree d, with nonzero constant coefficient, and x generates the multiplicative group of F_q[x]/(f), that is `order` = q^d - 1. Refused when q^d is 2^32 or more, because the answer is found by walking the powers of x.\", \"value\": \"boolean\"}, {\"name\": \"order\", \"summary\": \"The order of the member: writing f = x^h g with g(0) != 0, the least e >= 1 with g dividing x^e - 1, that is the multiplicative order of x in F_q[x]/(g). It is 1 when g is constant (f = x^h). Refused when q^d is 2^32 or more, because the answer is found by walking the powers of x.\", \"value\": \"integer\"}, {\"name\": \"roots\", \"summary\": \"The distinct roots of the member in F_q, in increasing order; multiplicities are not repeated.\", \"value\": \"polynomials_fq.elements\"}, {\"name\": \"root_count\", \"summary\": \"How many distinct roots the member has in F_q; the length of `roots`.\", \"value\": \"integer\"}, {\"args\": {\"other\": \"vector\"}, \"name\": \"gcd\", \"summary\": \"The monic gcd of the member and the fixed monic polynomial `other` (a 1 x k row read the same way as a member, so it is x^k + sum b_i x^i), returned in the same convention: the list [c_0, ..., c_{m-1}] of the coefficients below the leading term, so its length is the degree of the gcd and the empty list is the constant 1.\", \"value\": \"polynomials_fq.elements\"}], \"rejections\": [{\"case\": \"two rows per member F_2\", \"error\": \"one row\", \"op\": \"is_irreducible\"}, {\"case\": \"two rows per member F_2\", \"error\": \"one row\", \"op\": \"factorisation_degrees\"}, {\"case\": \"naturals family\", \"error\": \"no available backend accepts\", \"op\": \"root_count\"}, {\"case\": \"degree 32 over F_2\", \"error\": \"residue ring\", \"op\": \"order\"}, {\"case\": \"degree 32 over F_2\", \"error\": \"residue ring\", \"op\": \"is_primitive\"}]}, {\"backends\": [{\"accepts\": \"subsets of coordinate rows over any prime p < 2^32; line and hyperplane incidence is precomputed once per request\", \"name\": \"generic\", \"sources\": [\"backends/generic/projective_sets_generic.cpp\"], \"summary\": \"Portable C++: precomputes dictionary incidence with every line or hyperplane, then evaluates members in parallel.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Projective_sets/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"projective_sets\", \"reference\": \"lean/Projective_sets/Reference.lean\", \"summary\": \"Point sets in PG(n,p), given as subsets of distinct normalised nonzero coordinate rows over F_p. Arc means every n+1 points are independent; cap means no three are collinear. Secant, tangent and passant counts range over every projective line.\", \"version\": 1}, \"operations\": [{\"families\": [\"subsets\"], \"name\": \"is_arc\", \"summary\": \"Whether every n+1 selected points of PG(n,p) are linearly independent, equivalently every hyperplane contains at most n points.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"is_cap\", \"summary\": \"Whether no projective line contains three selected points.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"is_blocking_set\", \"summary\": \"Whether the set meets every projective hyperplane.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"is_hyperoval\", \"summary\": \"Whether the set is a 4-point cap in PG(2,2), the only even field supported by the prime-field runtime.\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"is_ovoid\", \"summary\": \"Whether the set is a cap of p^2+1 points in PG(3,p).\", \"value\": \"boolean\"}, {\"families\": [\"subsets\"], \"name\": \"max_collinear\", \"summary\": \"The largest intersection with a projective line; 0 when the ambient space has no lines.\", \"value\": \"integer\"}, {\"families\": [\"subsets\"], \"name\": \"spanned_rank\", \"summary\": \"Vector-space rank of the selected homogeneous coordinate rows, one more than the projective dimension of a nonempty span.\", \"value\": \"integer\"}, {\"families\": [\"subsets\"], \"name\": \"secant_count\", \"summary\": \"Number of projective lines containing exactly two selected points.\", \"value\": \"integer\"}, {\"families\": [\"subsets\"], \"name\": \"tangent_count\", \"summary\": \"Number of projective lines containing exactly one selected point.\", \"value\": \"integer\"}, {\"families\": [\"subsets\"], \"name\": \"passant_count\", \"summary\": \"Number of projective lines containing no selected point.\", \"value\": \"integer\"}], \"rejections\": [{\"case\": \"explicit point set\", \"error\": \"subsets\"}, {\"case\": \"zero projective point\", \"error\": \"contains zero\"}, {\"case\": \"unnormalised projective point\", \"error\": \"not normalised\"}, {\"case\": \"duplicate projective point\", \"error\": \"contains a duplicate\"}]}, {\"backends\": [{\"accepts\": \"any modulus below 2^32; ranges of residues or of moduli\", \"name\": \"generic\", \"sources\": [\"backends/generic/residues_generic.cpp\"], \"summary\": \"Portable C++: factors the modulus and phi(n) once per request, then answers each member with modular exponentiation; discrete logarithms use baby-step giant-step over a baby table shared by every member, after the standard reduction that removes the common factors of a non-unit base; the Jacobi symbol uses quadratic reciprocity.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Residues/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"residues\", \"reference\": \"lean/Residues/Reference.lean\", \"summary\": \"Arithmetic in Z/n over ranges of residues: multiplicative order, primitive roots, quadratic residues, discrete logarithms and the Legendre and Jacobi symbols. Members of a `range` family are residues reduced modulo the `modulus` argument, except `least_primitive_root`, whose member is the modulus. Canonical answers where mathematics leaves a choice: an order is 0 when the residue is not a unit; a discrete logarithm is the least x < n, and the modulus itself when there is none; a symbol is 0, 1, or 2 with 2 standing for -1; the least primitive root is 0 when (Z/n)* is not cyclic.\", \"version\": 1}, \"operations\": [{\"args\": {\"modulus\": \"int\"}, \"families\": [\"range\"], \"name\": \"multiplicative_order\", \"summary\": \"The least k >= 1 with a^k = 1 in Z/n for the member a, and 0 when a is not a unit.\", \"value\": \"integer\"}, {\"args\": {\"modulus\": \"int\"}, \"families\": [\"range\"], \"name\": \"is_primitive_root\", \"summary\": \"Whether the member generates the unit group of Z/n: a unit whose multiplicative order is phi(n).\", \"value\": \"boolean\"}, {\"args\": {\"modulus\": \"int\"}, \"families\": [\"range\"], \"name\": \"is_quadratic_residue\", \"summary\": \"Whether the member is a unit of Z/n with a square root there. Non-units, including 0, are not quadratic residues.\", \"value\": \"boolean\"}, {\"args\": {\"base\": \"int\", \"modulus\": \"int\"}, \"families\": [\"range\"], \"name\": \"discrete_log\", \"summary\": \"The least x with 0 <= x < n and base^x = a in Z/n for the member a; n itself when no such x exists. Any solution is smaller than n, so the modulus is unambiguous as the absent answer.\", \"value\": \"integer\"}, {\"args\": {\"modulus\": \"int\"}, \"families\": [\"range\"], \"name\": \"legendre\", \"summary\": \"The Legendre symbol (a/p) of the member for an odd prime modulus p, encoded 0 for 0, 1 for 1, and 2 for -1.\", \"value\": \"integer\"}, {\"args\": {\"modulus\": \"int\"}, \"families\": [\"range\"], \"name\": \"jacobi\", \"summary\": \"The Jacobi symbol (a/n) of the member for an odd modulus n, the product of the Legendre symbols over the prime factorisation of n, in the same 0, 1, 2 encoding. (a/1) is 1.\", \"value\": \"integer\"}, {\"families\": [\"range\"], \"name\": \"least_primitive_root\", \"summary\": \"Reads the member as a modulus n >= 1: the least g >= 1 that generates the unit group of Z/n, and 0 when (Z/n)* is not cyclic. It is 1 for n = 1 and n = 2.\", \"value\": \"integer\"}], \"rejections\": [{\"case\": \"not a range\", \"error\": \"range families only\"}, {\"case\": \"modulus zero\", \"error\": \"modulus of at least 1\"}, {\"case\": \"modulus too large\", \"error\": \"modulus less than\"}, {\"case\": \"even legendre modulus\", \"error\": \"odd prime\"}, {\"case\": \"composite legendre modulus\", \"error\": \"odd prime\"}, {\"case\": \"even jacobi modulus\", \"error\": \"odd modulus\"}, {\"case\": \"moduli from zero\", \"error\": \"moduli of at least 1\"}]}, {\"backends\": [{\"accepts\": \"subsets_of(words(2,n),m); n <= 22 follows from the runtime's materialisation limit\", \"name\": \"generic\", \"sources\": [\"backends/generic/set_systems_generic.cpp\"], \"summary\": \"Portable C++: depth-first outer-subset enumeration, pruning a subtree as soon as its prefix violates an intersection, antichain, sunflower, EKR, or Sperner predicate; incremental degrees and lower shadows.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Set_systems/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"set_systems\", \"reference\": \"lean/Set_systems/Reference.lean\", \"summary\": \"Extremal predicates on m-set systems represented by subsets_of(words(2,n),m): intersection, antichains, sunflowers, degree, lower shadow, and exact EKR/Sperner extremality checks.\", \"version\": 1}, \"operations\": [{\"families\": [\"subsets_of\"], \"name\": \"is_intersecting\", \"summary\": \"Every two distinct sets in the system intersect. A one-set system is intersecting.\", \"value\": \"boolean\"}, {\"families\": [\"subsets_of\"], \"name\": \"is_antichain\", \"summary\": \"No two distinct sets in the system contain one another.\", \"value\": \"boolean\"}, {\"args\": {\"k\": \"int\"}, \"families\": [\"subsets_of\"], \"name\": \"is_sunflower_free\", \"summary\": \"The system contains no k distinct sets whose pairwise intersections are all equal; k must be at least 2.\", \"value\": \"boolean\"}, {\"families\": [\"subsets_of\"], \"name\": \"max_degree\", \"summary\": \"Maximum, over ground elements, of the number of sets containing that element.\", \"value\": \"integer\"}, {\"families\": [\"subsets_of\"], \"name\": \"shadow_size\", \"summary\": \"Cardinality of the lower shadow: the union of all sets obtained by deleting one element from one member set.\", \"value\": \"integer\"}, {\"families\": [\"subsets_of\"], \"name\": \"is_ekr_extremal\", \"summary\": \"True exactly for a nonempty r-uniform intersecting system on n points with r >= 1, n >= 2r, and size C(n-1,r-1).\", \"value\": \"boolean\"}, {\"families\": [\"subsets_of\"], \"name\": \"is_sperner_extremal\", \"summary\": \"True exactly for an antichain on n points of size C(n,floor(n/2)).\", \"value\": \"boolean\"}], \"rejections\": [{\"case\": \"subsets of integers\", \"error\": \"family of the form\"}, {\"case\": \"ternary words\", \"error\": \"family of the form\"}, {\"case\": \"sunflower k=1\", \"error\": \"k must be at least 2\"}]}, {\"backends\": [{\"accepts\": \"families of 0/1 matrices over F_2 with at most 64 columns; any prime p < 2^32; at most 2^22 faces per member; boundary matrices of at most 2^24 entries; at most 20 facets for is_shellable\", \"name\": \"generic\", \"sources\": [\"backends/generic/simplicial_complexes_generic.cpp\"], \"summary\": \"Portable C++: faces as 64-bit vertex masks, enumerated by submask walk (nonfaces=0) or by depth-first extension that never leaves the complex (nonfaces=1), sorted so each dimension is a contiguous block; boundary matrices are eliminated as bitsets over F_2 and densely over any other prime, and shellability is a memoised search over subsets of the facets. Threaded over members.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Simplicial_complexes/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"simplicial_complexes\", \"reference\": \"lean/Simplicial_complexes/Reference.lean\", \"summary\": \"Simplicial complexes carried by 0/1 matrices over F_2: each row is a face that generates the complex (nonfaces=0) or a forbidden set that cuts it out (nonfaces=1, weight-2 rows giving the independence complex of a graph). Faces are the nonempty sets of the complex, so homology is unreduced: betti(p, i) = f_i - rank(boundary_i) - rank(boundary_{i+1}) over F_p, and f_count(i) is the i-th entry of the f-vector. euler_characteristic returns the alternating sum of the f-vector reduced modulo p, in [0, p), because the runtime's integer channel is unsigned. is_shellable is shellability in the sense of Bjorner-Wachs, non-pure allowed: some ordering F_1, ..., F_t of the facets has, for every j > 1 and i < j, some k < j with F_i n F_j subset of F_k and |F_j \\\\ F_k| = 1; a complex with at most one facet is shellable.\", \"version\": 1}, \"operations\": [{\"args\": {\"dim\": \"int\", \"nonfaces\": \"int\"}, \"name\": \"f_count\", \"summary\": \"f_dim: the number of faces with dim+1 vertices. Zero above the dimension of the complex, so the f-vector is this operation over dim = 0, 1, 2, ...\", \"value\": \"integer\"}, {\"args\": {\"nonfaces\": \"int\"}, \"name\": \"faces\", \"summary\": \"The number of nonempty faces, the sum of the f-vector.\", \"value\": \"integer\"}, {\"args\": {\"nonfaces\": \"int\", \"p\": \"int\"}, \"name\": \"euler_characteristic\", \"summary\": \"The Euler characteristic sum_i (-1)^i f_i reduced modulo the prime p, in [0, p). Integers cross the boundary unsigned, so a signed answer needs p above the range in play: with p = 65537 a value v > p/2 means the characteristic v - p.\", \"value\": \"integer\"}, {\"args\": {\"dim\": \"int\", \"nonfaces\": \"int\", \"p\": \"int\"}, \"name\": \"betti\", \"summary\": \"dim_{F_p} H_dim(Delta; F_p) for unreduced simplicial homology: f_dim - rank(boundary_dim) - rank(boundary_{dim+1}) over F_p, with boundary_0 = 0. beta_0 is the number of connected components; beta_dim is 0 above the dimension of the complex.\", \"value\": \"integer\"}, {\"args\": {\"nonfaces\": \"int\"}, \"name\": \"is_shellable\", \"summary\": \"Whether the facets admit a shelling order in the sense of Bjorner-Wachs (non-pure allowed): an order F_1, ..., F_t such that for every j > 1 and every i < j there is k < j with F_i n F_j contained in F_k and |F_j \\\\ F_k| = 1. Complexes with at most one facet, including the void complex, are shellable.\", \"value\": \"boolean\"}], \"rejections\": [{\"case\": \"graphs over F_3\", \"error\": \"over F_2\"}, {\"case\": \"nonfaces flag out of range\", \"error\": \"nonfaces must be 0 or 1\"}, {\"case\": \"composite modulus\", \"error\": \"prime\"}, {\"case\": \"triangles on 5 vertices\", \"error\": \"does not accept\", \"op\": \"is_shellable\", \"reduction\": \"histogram\"}, {\"case\": \"triangles on 5 vertices\", \"error\": \"does not accept\", \"op\": \"betti\", \"reduction\": \"count\"}]}, {\"backends\": [{\"accepts\": \"Any p < 2^32 and Grassmannian-derived transform/stack family whose ambient Grassmannian size at each encountered rank fits u64; group closure up to 2^26 elements.\", \"name\": \"generic\", \"sources\": [\"backends/generic/subspace_orbits_generic.cpp\"], \"summary\": \"Portable C++: canonical rref and breadth-first orbit search per member, threaded over family members.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Subspace_orbits/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"subspace_orbits\", \"reference\": \"lean/Subspace_orbits/Reference.lean\", \"summary\": \"GL and projective linear orbits of Grassmannian families and their transform/stack derivatives. Representatives are the least rref subspaces in Grassmannian order. Set projective=0 for the generated GL group and projective=1 for its image modulo nonzero scalars. Over the runtime's prime fields, PGammaL equals PGL.\", \"version\": 1}, \"operations\": [{\"args\": {\"group\": \"group\", \"projective\": \"int\"}, \"families\": [\"grassmannian\", \"transform\", \"stack\"], \"name\": \"is_canonical\", \"summary\": \"Whether the member's row space is the least subspace in its orbit. Subspaces are ordered by their canonical rref's index in grassmannian(p, n, rank).\", \"value\": \"boolean\"}, {\"args\": {\"group\": \"group\", \"projective\": \"int\"}, \"families\": [\"grassmannian\", \"transform\", \"stack\"], \"name\": \"canonical_index\", \"summary\": \"Index of the least orbit representative in grassmannian(p, n, rank), where rank and n belong to this member's row space.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\", \"projective\": \"int\"}, \"families\": [\"grassmannian\", \"transform\", \"stack\"], \"name\": \"orbit_size\", \"summary\": \"Number of distinct row spaces in the member's orbit. The projective flag does not change the orbit.\", \"value\": \"integer\"}, {\"args\": {\"group\": \"group\", \"projective\": \"int\"}, \"families\": [\"grassmannian\", \"transform\", \"stack\"], \"name\": \"stabilizer_order\", \"summary\": \"Order of the stabilizer: |generated GL group|/orbit_size when projective=0, or |its image modulo nonzero scalars|/orbit_size when projective=1.\", \"value\": \"integer\"}], \"rejections\": [{\"case\": \"permutations on subspaces\", \"error\": \"gfp.matrix\"}, {\"case\": \"all matrices are not a subspace family\", \"error\": \"families only\"}, {\"case\": \"wrong group dimension\", \"error\": \"n x n\"}, {\"case\": \"singular generator\", \"error\": \"invertible\"}, {\"case\": \"invalid projective flag\", \"error\": \"projective\"}]}, {\"backends\": [{\"accepts\": \"partition operations through n=30; RSK when its materialised output has at most 2^31 u32 entries; any representable standard_tableaux family\", \"name\": \"generic\", \"sources\": [\"backends/generic/young_generic.cpp\"], \"summary\": \"Portable C++: hook products, row-insertion RSK, recursive semistandard fillings, and memoised Murnaghan-Nakayama over subpartitions. Members run in parallel.\"}], \"kinds\": [{\"lean\": \"character\", \"name\": \"young.characters\", \"params\": [\"count\"], \"payload\": \"count signed i64 character values\", \"summary\": \"One signed Murnaghan-Nakayama character value per member.\"}, {\"lean\": \"rsk\", \"name\": \"young.rsk_pairs\", \"params\": [\"count\", \"length\"], \"payload\": \"count*length u32 row lengths, then two count*length*length u32 padded tableaux\", \"summary\": \"For each word, its common shape padded to length entries, followed by the insertion and recording tableaux padded to length x length squares.\"}], \"module\": {\"cases\": \"cases.py\", \"contract\": \"lean/Young/Contract.lean\", \"lean\": \"lean\", \"naive\": \"naive/naive.py\", \"name\": \"young\", \"reference\": \"lean/Young/Reference.lean\", \"summary\": \"Partitions and standard Young tableaux with hook-length counts, Kostka numbers, row-insertion RSK, and signed S_n character values from Murnaghan-Nakayama. Partitions are descending lexicographically; tableaux recursively place the largest entry in removable corners from top to bottom; RSK bumps the first strictly larger row entry.\", \"version\": 1}, \"operations\": [{\"args\": {\"weight\": \"vector\"}, \"families\": [\"partitions\"], \"name\": \"kostka\", \"summary\": \"Kostka number K_shape,weight: semistandard tableaux with weak rows, strict columns, and weight[i] copies of i.\", \"value\": \"integer\"}, {\"families\": [\"words\"], \"name\": \"rsk\", \"summary\": \"Robinson-Schensted-Knuth row insertion. Letters retain their 0-based values; recording entries are 1..length; the first row entry strictly greater than the inserted letter is bumped.\", \"value\": \"young.rsk_pairs\"}, {\"args\": {\"cycle_type\": \"vector\"}, \"families\": [\"partitions\"], \"name\": \"murnaghan_nakayama\", \"summary\": \"The irreducible S_n character indexed by each shape at the positive weakly decreasing cycle type, computed by Murnaghan-Nakayama. Signed values use little-endian two's-complement i64.\", \"value\": \"young.characters\"}, {\"families\": [\"partitions\", \"standard_tableaux\"], \"name\": \"hook_length_count\", \"summary\": \"Number of standard Young tableaux of the member's shape. On a standard_tableaux family, every member has the family's fixed shape.\", \"value\": \"integer\"}], \"rejections\": [{\"case\": \"bad Kostka weight\", \"error\": \"weight must sum\"}, {\"case\": \"bad cycle type\", \"error\": \"cycle_type must be a positive weakly decreasing partition\"}, {\"case\": \"RSK on partitions\", \"error\": \"words families only\"}]}], \"runtime\": {\"families\": [{\"lean\": \"explicit\", \"member\": \"matrix\", \"name\": \"explicit\", \"summary\": \"One member per matrix or permutation of the batch, in batch order.\"}, {\"lean\": \"subsets\", \"member\": \"matrix\", \"name\": \"subsets\", \"summary\": \"Every k-row matrix formed by choosing k rows of a matrix or permutation dictionary, indices increasing; lexicographic order of the index tuple.\"}, {\"lean\": \"grassmannian\", \"member\": \"gfp.matrix\", \"name\": \"grassmannian\", \"summary\": \"Every h-dimensional subspace of a field with q labelled elements as its reduced row echelon basis (h x n); ordered by pivot set (lexicographic), then by free entries (row-major, lexicographic). The consuming module supplies extension-field arithmetic.\"}, {\"lean\": \"allMatrices\", \"member\": \"gfp.matrix\", \"name\": \"all_matrices\", \"summary\": \"Every rows x cols matrix with entries 0..q-1; index is the row-major base-q number of the entries.\"}, {\"lean\": \"transform\", \"member\": \"gfp.matrix\", \"name\": \"transform\", \"summary\": \"Each prime-field member M replaced by M * C for a fixed matrix C. Same order and indices.\"}, {\"lean\": \"stack\", \"member\": \"gfp.matrix\", \"name\": \"stack\", \"summary\": \"Each member M of the inner family with a fixed block of rows appended below it. Same order and indices.\"}, {\"lean\": \"groupElements\", \"member\": \"orbits.perms | gfp.matrix\", \"name\": \"group_elements\", \"summary\": \"Every element of the group generated by an orbits.perms batch or invertible square gfp.matrix batch, in lexicographic order of the flat member. Size is the group order.\"}, {\"lean\": \"groupTables\", \"member\": \"lk.naturals\", \"name\": \"group_tables\", \"summary\": \"Finite groups as n x n Cayley tables with entries in 0..n-1, in stored order. A table batch gives explicit groups or a complete stored catalogue; permutation generators are converted to one table with lexicographically ordered elements.\"}, {\"lean\": \"subsetsOf\", \"member\": \"gfp.matrix\", \"name\": \"subsets_of\", \"summary\": \"Every k-subset of the members of an inner family, each member flattened to one row of rows*cols entries, indices increasing; lexicographic order of the index tuple. The inner family is materialised once and must have at most 2^22 members.\"}, {\"lean\": \"symmetricMatrices\", \"member\": \"gfp.matrix\", \"name\": \"symmetric_matrices\", \"summary\": \"Every symmetric n x n matrix with entries 0..q-1; index is the base-q number of the upper triangle read row-major.\"}, {\"lean\": \"range\", \"member\": \"lk.naturals\", \"name\": \"range\", \"summary\": \"The integers a <= x < b as 1 x 1 natural-number matrices; index is x - a.\"}, {\"lean\": \"words\", \"member\": \"lk.naturals\", \"name\": \"words\", \"summary\": \"Every word of the given length over the alphabet 0..alphabet-1 as a 1 x length natural-number matrix; index is the base-alphabet number of the word.\"}, {\"lean\": \"partitions\", \"member\": \"lk.naturals\", \"name\": \"partitions\", \"summary\": \"Partitions of total with optional largest-part, part-count and multiplicity bounds, and optional distinct or odd parts; one decreasing row padded to total entries with zeros, in descending lexicographic order. A zero bound is unrestricted.\"}, {\"lean\": \"compositions\", \"member\": \"lk.naturals\", \"name\": \"compositions\", \"summary\": \"Positive compositions of total with optional exact length and largest-part bound; one row padded to total entries with zeros. Lengths increase first, then rows are descending lexicographic. A zero bound or length is unrestricted.\"}, {\"lean\": \"standardTableaux\", \"member\": \"lk.naturals\", \"name\": \"standard_tableaux\", \"summary\": \"Every standard Young tableau of a fixed positive partition shape, padded with zeros to its bounding rectangle. Order recursively places the largest entry in removable corners from the top row down.\"}], \"kinds\": [{\"lean\": \"naturals\", \"name\": \"lk.naturals\", \"params\": [\"count\", \"rows\", \"cols\"], \"payload\": \"count*rows*cols u32 natural numbers\", \"summary\": \"A batch of natural-number matrices with entries below 2^32.\"}], \"reductions\": [{\"accepts\": [\"*\"], \"name\": \"all\", \"summary\": \"Materialise the per-member value for every member, in family order. Integers and booleans come back as kind `integers`.\"}, {\"accepts\": [\"boolean\"], \"name\": \"count\", \"summary\": \"Number of members whose value is true (kind `count`: value, visited, family_size).\"}, {\"accepts\": [\"integer\"], \"name\": \"histogram\", \"summary\": \"Number of members per value (kind `histogram`: u64 bins[0..max]).\"}, {\"accepts\": [\"boolean\"], \"args\": {\"limit\": \"int\"}, \"name\": \"hits\", \"summary\": \"Canonical indices of every member whose value is true, and the first `limit` of them materialised (kind `hits`).\"}, {\"accepts\": [\"boolean\"], \"name\": \"first\", \"summary\": \"The least canonical index whose value is true, materialised, or found = 0 when there is none (kind `first`). Stops as soon as nothing below the best hit remains; `visited` is index + 1 when found and family_size otherwise.\"}, {\"accepts\": [\"integer\"], \"name\": \"sum\", \"summary\": \"Sum of the values over the family (kind `count`: value, visited, family_size); fails if it exceeds 2^64 - 1.\"}, {\"accepts\": [\"integer\"], \"name\": \"max\", \"summary\": \"The largest value and the least index attaining it, materialised (kind `extremum`).\"}, {\"accepts\": [\"integer\"], \"name\": \"min\", \"summary\": \"The smallest value and the least index attaining it, materialised (kind `extremum`).\"}]}}";
